from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_debug


class Webem:
    """ Represents WebEM interface which allows to perform operations on BTS using web browser. """

    def __init__(self,
                 sw_stream: str,
                 selenium_alias: str):
        """
        :param sw_stream: software stream, e.g. '26R1'
        :param selenium_alias: name of opened selenium connection
        """
        self._selenium = None
        self._sw_stream = f'COAM{sw_stream}'
        self._selenium_alias = selenium_alias
        self._is_logged_in = False

    @property
    def is_logged_in(self) -> bool:
        """ Returns True if the browser session is active and logged into WebEM, False otherwise. """
        return self._is_logged_in

    @pretty_log
    def login(self, url: str, username: str, password: str, browser: str = 'Chrome', is_headless: bool = True,
              timeout: int = 60):
        """
        Logs into WebEM.
        :param url: url to WebEM, e.g. 'https://192.168.255.129'
        :param username: username to log in
        :param password: password to log in
        :param browser: browser to be used, supported browsers: 'Chrome', 'Firefox'; defaults to 'Chrome'
        :param is_headless: if True, browser will run in headless mode, defaults to True
        :param timeout: timeout for the element to be available to click, defaults to 60 seconds
        """
        self._selenium.login(url=url,
                             username=username,
                             password=password,
                             browser=browser,
                             is_headless=is_headless,
                             timeout=timeout,
                             coam=self._selenium_alias,
                             version=self._sw_stream)
        self._is_logged_in = True

    @pretty_log
    def logout(self, timeout: int = 60):
        """
        Logs out from WebEM.
        :param timeout: timeout for the element to be available to click, defaults to 60 seconds
        """
        self._selenium.logout(timeout=timeout,
                              coam=self._selenium_alias)
        self._is_logged_in = False

    @pretty_log
    def enable_virtual_display(self):
        """
        Enables virtual display - if enabled, browser window will not be displayed on screen.
        In order for this functionality to work correctly this method must be called before login method is called.
        """
        log_debug('Please make sure “xvfb” service is installed in the environment.')
        self._selenium.enable_virtual_display()

    @pretty_log
    def disable_virtual_display(self):
        """
        Disables virtual display.
        """
        self._selenium.disable_virtual_display()

    @pretty_log
    def set_download_dir_path(self, download_dir_path: str):
        """
        Sets path to the directory where files downloaded by browser will be saved.
        In order for this functionality to work correctly this method must be called before login method is called.

        :param download_dir_path: path to the directory where files downloaded by browser will be saved
        """
        self._selenium.set_download_dir(download_dir=download_dir_path)

    @pretty_log
    def set_debug_dir_path(self, debug_dir_path: str):
        """
        Sets path to the directory where debug files (e.g. screenshots) will be saved.
        In order for this functionality to work correctly this method must be called before login method is called.
        :param debug_dir_path: path to the directory where debug files will be saved
        """
        self._selenium.set_debug_dir(debug_dir=debug_dir_path)
